'use strict';
const $=s=>document.querySelector(s);
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money={Paid:'Paid',Unpaid:'Unpaid',Deposit:'Deposit paid'};
const labels={new:'To order',ordered:'Ordered',dispatched:'On the way',partial:'Part received',received:'Ready',notified:'Notified · sample',collected:'Complete'};
let gmailStatus=null,gmailResults=[];
let orders=[],view=location.hash==='#deliveries'?'deliveries':'orders',tab='all',query='',supplier='',payment='',selected=new Set(),currentId=null,pollBusy=false;
const days=date=>date?Math.max(0,Math.floor((Date.now()-new Date(date))/86400000)):0;
const date=s=>s?new Date(s).toLocaleDateString('en-GB',{day:'numeric',month:'short'}):'—';
const timestamp=s=>new Date(s).toLocaleString('en-GB',{day:'numeric',month:'short',hour:'2-digit',minute:'2-digit',timeZone:'Europe/Brussels'});
const active=o=>o.status!=='collected';
function alertFor(o){
if(o.supplier==='Lehmanns'&&o.status==='ordered'&&o.orderedAt&&days(o.orderedAt)>=3)return {level:days(o.orderedAt)>=6?'red':'orange',text:`${days(o.orderedAt)} days · no dispatch`,task:days(o.orderedAt)>=6?'Chase dispatch confirmation':'Check dispatch confirmation'};
if(o.status==='partial')return {level:'orange',text:o.damaged?'Damage / shortage':'Partial delivery',task:'Resolve delivery discrepancy'};
return null;
}
function badge(o){const a=alertFor(o);const color=a?.level||({new:'',ordered:'blue',dispatched:'purple',partial:'orange',received:'green',notified:'green',collected:''}[o.status]);return `<span class="badge ${color}">${esc(a?.text||labels[o.status])}</span>`;}
async function api(url,body){const r=await fetch(url,body?{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)}:undefined);const data=await r.json();if(!r.ok)throw Error(data.error||'Request failed');return data;}
function toast(text){$('#toast').textContent=text;$('#toast').hidden=false;clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').hidden=true,4500);}
async function load(){orders=await api('/api/orders');selected=new Set([...selected].filter(id=>orders.some(o=>o.id===id)));$('#save-status').textContent='Saved to this workspace';}
function statHTML(){const open=orders.filter(active),needs=open.filter(alertFor),ready=open.filter(o=>['received','notified'].includes(o.status));const month=new Date().toISOString().slice(0,7),completed=orders.filter(o=>o.status==='collected'&&o.history.some(h=>h.at.startsWith(month)&&/collected|shelved/.test(h.text)));
return [[open.length,'Open orders','Across all suppliers','▦',''],[needs.length,'Need attention','Follow up before they fall behind','◷','attention'],[ready.length,'Ready for collection','Received & waiting in the shop','▣','ready'],[completed.length,'Completed this month','A little progress, every day','✓','']].map(([n,t,sub,i,c])=>`<div class="stat ${c}"><div class="stat-top">${t}<span class="stat-icon">${i}</span></div><div class="stat-value">${n}</div><small>${sub}</small></div>`).join('');}
function filtered(){return orders.filter(o=>{
const term=query.toLowerCase();if(term&&!`${o.customer} ${o.book} ${o.reference} ${o.isbn} ${o.owner}`.toLowerCase().includes(term))return false;
if(supplier&&o.supplier!==supplier||payment&&o.payment!==payment)return false;
if(tab==='all')return true;if(tab==='attention')return !!alertFor(o);if(tab==='ready')return ['received','notified'].includes(o.status);if(tab==='overweek')return active(o)&&days(o.createdAt)>7;return o.status===tab;
});}
function table(rows,delivery=false){return `<div class="table-wrap"><table><thead><tr><th><input type="checkbox" id="select-all" aria-label="Select visible orders" ${rows.length&&rows.every(o=>selected.has(o.id))?'checked':''}></th><th>Order / product</th><th>Customer</th><th>Supplier</th><th>Status</th><th>${delivery?'Allocation':'Payment'}</th><th>Owner</th><th></th></tr></thead><tbody>${rows.map(o=>`<tr><td><input type="checkbox" data-select="${o.id}" aria-label="Select ${esc(o.reference)}" ${selected.has(o.id)?'checked':''}></td><td><button class="order-link" data-open="${o.id}"><strong>${esc(o.book)}</strong><span class="subtext">${esc(o.reference)} · ${o.quantity} ${o.quantity===1?'item':'items'} · ${date(o.createdAt)}</span></button></td><td><span class="customer-name">${esc(o.customer)}</span><span class="subtext">${o.kind==='Stock'?'Shop restocking':esc(o.channel)}</span></td><td>${esc(o.supplier||'Not placed')}<span class="subtext">${o.orderedAt?'Ordered '+date(o.orderedAt):'Waiting to order'}</span></td><td>${badge(o)}</td><td>${delivery?`<span>${o.received} / ${o.quantity} received</span><span class="subtext">${o.kind==='Stock'?'For shop shelf':'Reserved for customer'}</span>`:`<span class="payment ${esc(o.payment)}">${money[o.payment]}</span>`}</td><td><span class="avatar" title="${esc(o.owner)}">${esc(o.owner.slice(0,2).toUpperCase())}</span></td><td><button class="row-arrow" data-open="${o.id}" aria-label="Open ${esc(o.reference)}">›</button></td></tr>`).join('')||'<tr><td colspan="8" class="empty">No orders here. A little breathing room.</td></tr>'}</tbody></table></div>`;}
function followCard(){const list=orders.filter(o=>active(o)&&alertFor(o)).sort((a,b)=>days(b.orderedAt)-days(a.orderedAt));return `<div class="card"><div class="card-heading"><h3>Needs a little attention</h3><button data-go="tasks">All follow-ups ↗</button></div>${list.slice(0,3).map(o=>`<div class="follow-item"><span class="follow-icon ${alertFor(o).level}">!</span><div><strong>${esc(o.supplier)} · ${esc(alertFor(o).task)}</strong><small>${esc(o.reference)} · ${esc(o.customer)} · ${esc(o.owner)}</small></div><button data-open="${o.id}">Review →</button></div>`).join('')||'<p>Everything is up to date.</p>'}</div>`;}
function supplierCard(){const names=['Lehmanns','Friedman','Sifrei'];return `<div class="card"><div class="card-heading"><h3>Your supplier desk</h3><button data-go="deliveries">Delivery desk ↗</button></div>${names.map(n=>{const nopen=orders.filter(o=>active(o)&&o.supplier===n).length;return `<div class="supplier-row"><span class="supplier-mark">${n[0]}</span><div>${n}<small>${n==='Sifrei'?'Israel · fallback supplier':'England · daily ordering'}</small></div><b>${nopen} open orders</b></div><progress class="bar" max="100" value="${Math.max(8,nopen/Math.max(1,orders.filter(active).length)*100)}"></progress>`;}).join('')}</div>`;}
function renderOrders(){const tabs=[['all','All orders'],['new','To order'],['ordered','Ordered'],['ready','Ready'],['attention','Needs attention'],['collected','Complete']];const rows=filtered();$('#content').innerHTML=`<section class="panel"><div class="tabs">${tabs.map(([id,name])=>`<button data-tab="${id}" class="${tab===id?'active':''}">${name}<b>${orders.filter(o=>id==='all'||(id==='ready'?['received','notified'].includes(o.status):id==='attention'?alertFor(o):o.status===id)).length}</b></button>`).join('')}</div><div class="toolbar"><label class="search"><span>⌕</span><input id="search" placeholder="Search customer, book or order…" aria-label="Search orders" value="${esc(query)}"></label><select id="supplier-filter" aria-label="Filter supplier"><option value="">All suppliers</option>${['Lehmanns','Friedman','Sifrei','America','Other'].map(n=>`<option ${supplier===n?'selected':''}>${n}</option>`).join('')}</select><select id="payment-filter" aria-label="Filter payment"><option value="">All payments</option>${['Paid','Deposit','Unpaid'].map(n=>`<option ${payment===n?'selected':''}>${n}</option>`).join('')}</select><button class="secondary" id="export">↓ Export</button></div>${selected.size?`<div class="bulk-bar"><span>${selected.size} selected</span><button class="secondary" id="print-selected">Print labels</button><button class="primary" id="notify-selected">Try batch notification</button></div>`:''}${table(rows)}<div class="table-foot"><span>Showing ${rows.length} of ${orders.length} orders</span><span>Click an order to see its full story →</span></div></section><div class="bottom-grid">${followCard()}${supplierCard()}</div>`;bindTable(rows);}
function renderDeliveries(){renderInvoiceDesk();}
function renderTasks(){const rows=orders.filter(o=>active(o)&&alertFor(o));$('#content').innerHTML=`<section class="card task-list"><div class="card-heading"><h3>Follow-ups assigned to your team</h3><span class="badge orange">${rows.length} open</span></div>${rows.map(o=>`<div class="follow-item"><span class="follow-icon ${alertFor(o).level}">!</span><div><strong>${esc(alertFor(o).task)} · ${esc(o.reference)}</strong><small>${esc(o.customer)} · ${esc(o.book)}<br>Assigned to ${esc(o.owner)} · ${esc(alertFor(o).text)}</small></div><button data-open="${o.id}">Open order →</button></div>`).join('')||'<div class="empty">No outstanding follow-ups.</div>'}<p class="hint">Lehmanns: 3 / 6 calendar days after ordering without dispatch. Friedman: invoice is dispatch confirmation; its automatic deadlines are awaiting your confirmation. Sifrei has no configured deadline yet.</p></section>`;bindOpen();}
function renderReports(){const month=new Date().toISOString().slice(0,7);const completed=orders.filter(o=>o.receivedAt&&o.receivedAt.startsWith(month));const avg=rows=>rows.length?(rows.reduce((sum,o)=>sum+(new Date(o.receivedAt)-new Date(o.createdAt))/86400000,0)/rows.length).toFixed(1)+' days':'—';const old=orders.filter(o=>active(o)&&days(o.createdAt)>7);$('#content').innerHTML=`<div class="bottom-grid"><div class="card"><div class="eyebrow">REQUEST → FIRST ARRIVAL · THIS MONTH</div><h1>${avg(completed)}</h1><p>Across ${completed.length} orders with an arrival recorded this month. Partial arrivals count as first arrival.</p></div><div class="card"><div class="eyebrow">OUTSTANDING MORE THAN A WEEK</div><h1>${old.length}</h1><p>Customer and stock requests still open after 7 calendar days.</p></div></div><section class="panel report-table"><table><thead><tr><th>Supplier</th><th>Arrived this month</th><th>Average request → arrival</th><th>Open orders</th></tr></thead><tbody>${['Lehmanns','Friedman','Sifrei','America','Other'].map(s=>`<tr><td>${s}</td><td>${completed.filter(o=>o.supplier===s).length}</td><td>${avg(completed.filter(o=>o.supplier===s))}</td><td>${orders.filter(o=>active(o)&&o.supplier===s).length}</td></tr>`).join('')}</tbody></table></section><section class="panel report-table"><div class="card-heading card"><h3>Open more than a week</h3></div>${table(old)}</section>`;bindTable(old);}
function render(){const titles={inbox:['Supplier inbox','Four mailboxes, one supplier desk. Drafts stay in the right account.'],orders:['Customer orders','Every request, every delivery, every happy customer. All in one place.'],deliveries:['Delivery desk','Unpack with confidence. Every book has a place to go.'],tasks:['Follow-up tasks','The right person, the right next step. Nothing forgotten.'],reports:['A clearer picture','See what is moving, what is waiting, and where to focus.']};$('#new-order').textContent=view==='deliveries'?'＋ New invoice':'＋ New order';$('#page-title').textContent=titles[view][0];$('#page-description').textContent=titles[view][1];$('#breadcrumb').textContent=titles[view][0];$('#stats').innerHTML=statHTML();$('#nav-count').textContent=orders.filter(active).length;$('#task-count').textContent=orders.filter(o=>active(o)&&alertFor(o)).length;document.querySelectorAll('#nav button').forEach(b=>b.classList.toggle('active',b.dataset.view===view));({inbox:renderInbox,orders:renderOrders,deliveries:renderDeliveries,tasks:renderTasks,reports:renderReports}[view])();document.querySelectorAll('[data-go]').forEach(b=>b.onclick=()=>go(b.dataset.go));}
function go(v){view=v;selected.clear();render();}
function bindOpen(){document.querySelectorAll('[data-open]').forEach(b=>b.onclick=()=>showDetail(b.dataset.open));}
function bindTable(rows){bindOpen();const all=$('#select-all');if(all)all.onchange=()=>{rows.forEach(o=>all.checked?selected.add(o.id):selected.delete(o.id));render();};document.querySelectorAll('[data-select]').forEach(c=>c.onchange=()=>{c.checked?selected.add(c.dataset.select):selected.delete(c.dataset.select);render();});document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>{tab=b.dataset.tab;selected.clear();render();});if($('#search'))$('#search').oninput=e=>{const cursor=e.target.selectionStart;query=e.target.value;renderOrders();$('#search').focus();$('#search').setSelectionRange(cursor,cursor);};if($('#supplier-filter'))$('#supplier-filter').onchange=e=>{supplier=e.target.value;selected.clear();render();};if($('#payment-filter'))$('#payment-filter').onchange=e=>{payment=e.target.value;selected.clear();render();};if($('#export'))$('#export').onclick=()=>location.assign('/api/export');if($('#print-selected'))$('#print-selected').onclick=()=>printLabels(orders.filter(o=>selected.has(o.id)));if($('#notify-selected'))$('#notify-selected').onclick=batchNotify;}
function detailSummary(o){return `<div class="detail-summary">${[['Customer',o.customer],['Supplier',o.supplier||'Not chosen'],['Payment',money[o.payment]],['Contact',o.phone||o.email||'Not entered'],['Notify by',o.channel],['Responsible',o.owner],['Quantity',`${o.quantity} ordered · ${o.received} received`],['Shelf / location',o.location||'Not assigned'],['Order date',date(o.orderedAt)]].map(([k,v])=>`<div><small>${k}</small><strong>${esc(v)}</strong></div>`).join('')}</div>`;}
function showDetail(id){currentId=id;const o=orders.find(x=>x.id===id);if(!o)return;const a=alertFor(o);$('#detail-content').innerHTML=`<div class="modal-heading"><div><div class="eyebrow">${esc(o.reference)} · ${esc(o.kind.toUpperCase())} ORDER</div><h2>${esc(o.book)}</h2></div><button class="close" data-close="detail-dialog" aria-label="Close">×</button></div><div class="detail-body">${badge(o)}${a?`<p class="hint">${esc(a.task)} · assigned to ${esc(o.owner)}. Record a dispatch confirmation or add a follow-up note.</p>`:''}<p>${esc(o.notes)}</p>${detailSummary(o)}<div class="detail-actions">${o.status==='new'?'<button class="primary" id="place-order">Place order →</button>':''}${o.status==='ordered'?`<button class="secondary" id="dispatch">${o.supplier==='Friedman'?'Record invoice / dispatch':'Record dispatch confirmation'}</button>`:''}${['ordered','dispatched','partial','received'].includes(o.status)?'<button class="primary" id="receive">Check in delivery</button>':''}${o.status==='received'&&o.kind==='Customer'?'<button class="primary" id="notify-one">Try notification</button>':''}${['received','notified'].includes(o.status)?`<button class="secondary" id="collect">${o.kind==='Stock'?'Mark shelved':'Mark collected'}</button>`:''}<button class="secondary" id="edit-order">Edit details</button>${o.received?'<button class="secondary" id="print-one">Print label</button>':''}<button class="secondary" id="draft-email">Draft supplier email</button></div><div id="detail-work"></div><h3>Order history</h3><div class="timeline">${[...o.history].reverse().map(h=>`<div class="event"><p>${esc(h.text)}</p><small>${timestamp(h.at)} · ${esc(h.by)}</small></div>`).join('')}</div><form id="note-form"><label class="field-label">Add a follow-up note<textarea class="note-input" name="note" required placeholder="Supplier reply, customer request, next step…"></textarea></label><button class="secondary" type="submit">Add note</button></form></div>`;
if(!$('#detail-dialog').open)$('#detail-dialog').showModal();bindClose();
const bind=(id,fn)=>{if($(id))$(id).onclick=fn;};
bind('#place-order',()=>{$('#detail-work').innerHTML=`<form id="place-form" class="card"><label class="field-label">Supplier<select class="note-input" name="supplier" required><option value="">Choose supplier</option>${['Lehmanns','Friedman','Sifrei','America','Other'].map(s=>`<option ${o.supplier===s?'selected':''}>${s}</option>`).join('')}</select></label><p>Record this only after you have sent the order. This button does not email the supplier.</p><button class="primary">Record placed order</button></form>`;$('#place-form').onsubmit=async e=>{e.preventDefault();await update(o,'order',{supplier:new FormData(e.target).get('supplier')});};});
bind('#dispatch',()=>update(o,'dispatch'));
bind('#receive',()=>receiveForm(o));bind('#edit-order',()=>editForm(o));bind('#print-one',()=>printLabels([o]));bind('#draft-email',()=>draftForm(o));bind('#notify-one',()=>notificationPreview([o]));bind('#collect',()=>update(o,'collect'));$('#note-form').onsubmit=async e=>{e.preventDefault();await update(o,'note',{note:new FormData(e.target).get('note')});};
}
async function update(o,action,extra={}){try{const updated=await api('/api/orders/'+o.id,{action,version:o.version,...extra});await load();render();showDetail(updated.id);toast('Order saved');return true;}catch(e){toast(e.message);if(e.message.includes('Another employee')){await load();render();showDetail(o.id);}return false;}}
function receiveForm(o){$('#detail-work').innerHTML=`<form id="receive-form" class="card"><h3>Check in this delivery</h3><p>Enter total good items received so far and damaged items still awaiting replacement. Reduce damaged quantity when replacements arrive. Only good items become ready for collection.</p><div class="form-grid"><label>Good items received<input type="number" name="received" min="${o.received}" max="${o.quantity}" value="${o.received}" required></label><label>Damaged items<input type="number" name="damaged" min="0" max="${o.quantity}" value="${o.damaged}" required></label><label class="wide">Shelf / customer collection location<input name="location" value="${esc(o.location)}" placeholder="e.g. Collection shelf B2"></label></div><p class="hint">Allocated to ${esc(o.customer)} · ${o.kind==='Stock'?'shop stock':'customer reservation'}. Ordered: ${o.quantity}.</p><button class="primary">Save delivery check</button></form>`;$('#receive-form').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.target);await update(o,'receive',{received:Number(f.get('received')),damaged:Number(f.get('damaged')),location:f.get('location')});};}
function editForm(o){$('#detail-work').innerHTML=`<form id="edit-form" class="card"><h3>Edit order details</h3><div class="form-grid">${['customer','book','phone','email','owner','isbn','location'].map(k=>`<label>${k[0].toUpperCase()+k.slice(1)}<input name="${k}" value="${esc(o[k])}" ${['customer','book','owner'].includes(k)?'required':''} ${k==='email'?'type="email"':''}></label>`).join('')}<label>Quantity<input name="quantity" type="number" min="1" max="10000" value="${o.quantity}" required></label><label>Payment<select name="payment">${Object.keys(money).map(p=>`<option ${p===o.payment?'selected':''} value="${p}">${money[p]}</option>`).join('')}</select></label><label>Notify by<select name="channel">${['SMS','WhatsApp','Email','None'].map(c=>`<option ${c===o.channel?'selected':''}>${c}</option>`).join('')}</select></label><label class="wide">Notes<textarea name="notes">${esc(o.notes)}</textarea></label></div><p class="hint">Employee names are assignments in this sample workspace, not authenticated user identities.</p><button class="primary">Save changes</button></form>`;$('#edit-form').onsubmit=async e=>{e.preventDefault();const data=Object.fromEntries(new FormData(e.target));data.quantity=Number(data.quantity);await update(o,'edit',data);};}
function draftForm(o){const outstanding=o.quantity-o.received-o.damaged;const subject=`${o.reference} — ${o.damaged?'Damaged items':outstanding?'Outstanding items':'Order follow-up'}`;const text=`Dear ${o.supplier||'supplier'},\n\nPlease could you check our order ${o.reference}, placed ${date(o.orderedAt)}?\n\nItem: ${o.book}${o.isbn?'\nISBN / code: '+o.isbn:''}\nOrdered: ${o.quantity}\nReceived in good condition: ${o.received}\nDamaged: ${o.damaged}\nOutstanding: ${outstanding}\n\n${o.damaged?'Please advise on a replacement or credit.':outstanding?'Could you confirm availability and the expected dispatch date?':'Please let us know the latest status.'}\n\nThank you,\nTiferes Judaica`;
$('#detail-work').innerHTML=`<section class="card"><h3>Supplier email draft</h3><p>Review before sending. Gmail is not connected; this draft stays on this screen.</p><label class="field-label">Subject<input class="note-input" id="draft-subject" value="${esc(subject)}"></label><label class="field-label">Message<textarea class="note-input" id="draft-body" rows="12">${esc(text)}</textarea></label><label class="field-label">Damage photo (optional)<input id="damage-photo" type="file" accept="image/*" capture="environment"></label><img id="photo-preview" class="photo-preview" alt="Damage photo preview" hidden><p class="photo-note">Photo preview only: not uploaded, saved or attached to Gmail in this version.</p><button class="secondary" id="copy-draft">Copy draft</button></section>`;$('#copy-draft').onclick=async()=>{try{await navigator.clipboard.writeText($('#draft-subject').value+'\n\n'+$('#draft-body').value);toast('Draft copied. Attach the photo yourself when sending.');}catch{toast('Select the draft text to copy it.');}};let objectUrl;$('#damage-photo').onchange=e=>{const file=e.target.files[0];if(!file)return;if(!file.type.startsWith('image/'))return toast('Choose an image file.');if(objectUrl)URL.revokeObjectURL(objectUrl);objectUrl=URL.createObjectURL(file);$('#photo-preview').src=objectUrl;$('#photo-preview').hidden=false;};}
function notificationPreview(rows){const ready=rows.filter(o=>o.status==='received'&&o.kind==='Customer');const destination=$('#detail-dialog').open?$('#detail-work'):null;const html=`<section class="card"><h3>Batch notification · simulation</h3><p>${ready.length} ready customer order(s). ${rows.length-ready.length} selected order(s) not eligible.</p><p class="hint">No SMS, WhatsApp or email will be sent. This tests the workflow only; missing contact details do not block this simulation.</p>${ready.map(o=>`<div class="follow-item"><div><strong>${esc(o.customer)} · ${esc(o.channel)}</strong><small>Hi ${esc(o.customer)}, your order ${esc(o.reference)} is ready for collection at Tiferes Judaica. Thank you!</small></div></div>`).join('')}<button class="primary" id="confirm-simulation" ${!ready.length?'disabled':''}>Record ${ready.length} sample notification(s)</button></section>`;
if(destination)destination.innerHTML=html;else{$('#detail-content').innerHTML=`<div class="modal-heading"><h2>Notify customers</h2><button class="close" data-close="detail-dialog" aria-label="Close">×</button></div><div class="detail-body">${html}</div>`;$('#detail-dialog').showModal();bindClose();}
$('#confirm-simulation').onclick=async e=>{e.target.disabled=true;let n=0;try{for(const o of ready){await api('/api/orders/'+o.id,{action:'notify',version:o.version});n++;}await load();selected.clear();render();$('#detail-dialog').close();toast(`${n} sample notifications recorded. No messages were sent.`);}catch(err){await load();render();$('#detail-dialog').close();toast(`${n} recorded. ${err.message}`);}};
}
function batchNotify(){notificationPreview(orders.filter(o=>selected.has(o.id)));}
function printLabels(rows){const received=rows.filter(o=>o.received>0);if(!received.length)return toast('Receive items before printing collection labels.');$('#print-area').innerHTML=received.map(o=>`<div class="label"><small>TIFERES · ${esc(o.reference)}</small><h2>${esc(o.customer)}</h2><p>${esc(o.book)}</p><p>${o.received} good item(s) · ${esc(o.kind==='Stock'?'SHOP STOCK':o.channel)}<br>Location: ${esc(o.location||'Not assigned')}<br>Payment: ${money[o.payment]}</p></div>`).join('');window.print();}
function bindClose(){document.querySelectorAll('[data-close]').forEach(b=>b.onclick=()=>$('#'+b.dataset.close).close());}
$('#today').textContent=new Date().toLocaleDateString('en-GB',{weekday:'short',day:'numeric',month:'long',timeZone:'Europe/Brussels'});
document.querySelectorAll('#nav button').forEach(b=>b.onclick=()=>go(b.dataset.view));
$('#new-order').onclick=()=>{if(view==='deliveries')return newInvoice();$('#order-form').reset();$('#form-error').textContent='';$('#order-dialog').showModal();};
$('#connections-button').onclick=$('#notice-connections').onclick=()=>$('#connections-dialog').showModal();bindClose();
$('#order-form').onsubmit=async e=>{e.preventDefault();const submit=e.target.querySelector('[type=submit]');submit.disabled=true;const data=Object.fromEntries(new FormData(e.target));data.quantity=Number(data.quantity);data.location='';try{const o=await api('/api/orders',data);await load();view='orders';tab='all';query='';supplier='';payment='';render();$('#order-dialog').close();showDetail(o.id);toast('New order saved');}catch(err){$('#form-error').textContent=err.message;}finally{submit.disabled=false;}};
(async()=>{try{await load();render();}catch(e){$('#content').innerHTML='<div class="card"><h3>Could not load your orders</h3><p>Check that the app server is running, then refresh. Your records have not been changed.</p></div>';$('#save-status').textContent='Connection unavailable';}})();
setInterval(async()=>{if(pollBusy||document.hidden||document.querySelector('dialog[open]')||document.activeElement?.matches('input,textarea,select'))return;pollBusy=true;try{await load();render();}catch{$('#save-status').textContent='Reconnecting…';}finally{pollBusy=false;}},15000);

function renderInbox(){
 const st=gmailStatus;$('#content').innerHTML=`<section class="card"><div class="card-heading"><h3>Shop mailboxes</h3><button class="secondary" id="refresh-mailboxes">Refresh status</button></div><p>Read supplier emails and create reply drafts in the receiving account. This app has no send-email function.</p>${!st?'<p>Loading connection status…</p>':''}${st&&!st.configured?'<p class="hint">Google app setup is required: an OAuth client ID, client secret and registered callback address. Your Gmail chat plugin is separate. These mailboxes are not connected yet.</p>':''}<div class="mailbox-grid">${(st?.accounts||[]).map(a=>`<div class="integration"><b>${esc(a.email)}</b><span>${a.connected?'Authorised':'Not connected'}</span><p>${a.connected?'Google permission saved for this mailbox.':'Approve this Google account once to enable reading and draft creation.'}</p><button class="secondary" data-gmail-connect="${esc(a.email)}" ${!st?.configured?'disabled':''}>${a.connected?'Reconnect Google account':'Connect Google account'}</button></div>`).join('')}${st&&!st.accounts?.length?'<p>No mailbox list is configured on this server yet.</p>':''}</div></section><section class="card inbox-search"><h3>Find a supplier email</h3><form id="gmail-search" class="toolbar"><label class="search"><input name="query" aria-label="Supplier email search" required placeholder="Supplier name, email or order reference"></label><select name="email" aria-label="Search mailbox"><option value="">All authorised mailboxes</option>${(st?.accounts||[]).filter(a=>a.connected).map(a=>`<option>${esc(a.email)}</option>`).join('')}</select><button class="primary" ${!st?.accounts?.some(a=>a.connected)?'disabled':''}>Search emails</button></form><p class="hint">Searching does not mark messages read. Email content is shown as plain text. Order-reference matches are suggestions for staff to review.</p><div id="gmail-results">${gmailResults.map((m,i)=>{const refs=(m.subject+' '+m.text).match(/\bTF-\d+\b/g)||[];const matches=orders.filter(o=>refs.includes(o.reference));return `<div class="follow-item"><span class="follow-icon">✉</span><div><strong>${esc(m.subject||'(No subject)')}</strong><small>${esc(m.mailbox)} · ${esc(m.from)}<br>${matches.length?'Possible order: '+matches.map(o=>esc(o.reference)).join(', '):'No exact order reference matched — review manually'}</small></div><button data-gmail-message="${i}">Read & draft →</button></div>`;}).join('')}</div></section>`;
 $('#refresh-mailboxes').onclick=refreshMailboxes;
 document.querySelectorAll('[data-gmail-connect]').forEach(b=>b.onclick=async()=>{b.disabled=true;try{const r=await api('/api/gmail/connect?email='+encodeURIComponent(b.dataset.gmailConnect));location.assign(r.url);}catch(e){toast(e.message);b.disabled=false;}});
 $('#gmail-search').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.target),mailboxes=f.get('email')?[f.get('email')]:(gmailStatus?.accounts||[]).filter(a=>a.connected).map(a=>a.email);const button=e.target.querySelector('button');button.disabled=true;try{const results=await Promise.allSettled(mailboxes.map(email=>api('/api/gmail/messages?'+new URLSearchParams({email,query:f.get('query')}))));gmailResults=results.filter(r=>r.status==='fulfilled').flatMap(r=>r.value.messages);renderInbox();const failed=results.filter(r=>r.status==='rejected');if(failed.length)toast(failed[0].reason.message);else if(!gmailResults.length)toast('No matching emails found.');else toast('Showing up to 20 matching emails per mailbox.');}catch(err){toast(err.message);}finally{if(button.isConnected)button.disabled=false;}};
 document.querySelectorAll('[data-gmail-message]').forEach(b=>b.onclick=()=>showGmailMessage(gmailResults[Number(b.dataset.gmailMessage)]));
 if(!st)refreshMailboxes();
}
async function refreshMailboxes(){try{gmailStatus=await api('/api/gmail/status');if(view==='inbox')renderInbox();}catch(e){if(view==='inbox'){$('#content').innerHTML='<section class="card"><h3>Mailbox access is not available here</h3><p>'+esc(e.message)+'</p><p>Use the server version after Google setup; the public trial cannot access email.</p></section>';}}}
function showGmailMessage(m){$('#gmail-detail').innerHTML=`<div class="modal-heading"><div><div class="eyebrow">${esc(m.mailbox)}</div><h2>${esc(m.subject||'Supplier email')}</h2></div><button class="close" data-close="gmail-dialog" aria-label="Close">×</button></div><div class="form-body"><p>From: ${esc(m.from)}</p><pre class="draft mail-body">${esc(m.text||m.snippet||'No plain-text content. Open this email in Gmail to view its attachments or formatting.')}</pre><form id="gmail-draft"><label class="field-label">Draft reply<textarea class="note-input" name="body" required rows="7" placeholder="Write the follow-up you want to save in Gmail…"></textarea></label><p class="hint">Creates a real draft in ${esc(m.mailbox)}, attached to this email thread. It will not send the email.</p><button class="primary">Save draft in Gmail</button></form></div>`;$('#gmail-dialog').showModal();bindClose();$('#gmail-draft').onsubmit=async e=>{e.preventDefault();const b=e.target.querySelector('button');b.disabled=true;try{await api('/api/gmail/drafts',{email:m.mailbox,messageId:m.id,body:new FormData(e.target).get('body')});$('#gmail-dialog').close();toast('Draft saved in '+m.mailbox+'. No email sent.');}catch(err){toast(err.message);b.disabled=false;}};}

let invoices=[],invoiceFilter='all',invoiceSearch='',invoiceWorker='Sarah';
async function refreshInvoices(){invoices=await api('/api/invoices');}
async function renderInvoiceDesk(){try{await refreshInvoices();if(view!=='deliveries')return;const rows=invoices.filter(o=>(invoiceFilter==='all'||invoiceFilter==='open'&&o.status!=='checked'||invoiceFilter==='issues'&&o.status==='checked'&&(DeliveryModel.totals(o).missing||DeliveryModel.totals(o).damaged))&&`${o.number} ${o.supplier}`.toLowerCase().includes(invoiceSearch.toLowerCase()));$('#content').innerHTML=`<div class="notice"><span>▣</span><span><strong>Invoice check-in · supplier records only.</strong> Check the complete invoice, including shop stock. No customer information is included in these records or supplier drafts.</span></div><section class="panel"><div class="tabs">${[['all','All invoices'],['open','Waiting / in progress'],['issues','Checked with issues']].map(([id,label])=>`<button data-invoice-filter="${id}" class="${invoiceFilter===id?'active':''}">${label}</button>`).join('')}</div><div class="toolbar"><label class="search"><span>⌕</span><input id="invoice-search" aria-label="Find invoice" placeholder="Find invoice number or supplier…" value="${esc(invoiceSearch)}"></label><span class="hint compact-hint">Sample invoices are ready to try. Invoice-email import is not connected.</span></div><div class="table-wrap"><table><thead><tr><th>Invoice</th><th>Supplier</th><th>Expected</th><th>Invoiced</th><th>Progress</th><th>Result</th><th></th></tr></thead><tbody>${rows.map(o=>{const t=DeliveryModel.totals(o);return `<tr><td><button class="order-link" data-invoice="${o.id}"><strong>${esc(o.number)}</strong><span class="subtext">${o.lines.length} invoice lines</span></button></td><td>${esc(o.supplier)}</td><td>${date(o.expectedDate)}</td><td>${t.invoiced} units</td><td>${o.lines.length-t.unchecked} / ${o.lines.length} lines checked</td><td><span class="badge ${o.status==='checked'?(t.missing||t.damaged?'orange':'green'):o.status==='checking'?'blue':''}">${o.status==='checked'?(t.missing||t.damaged?'Checked · discrepancies':'Checked · complete'):o.status==='checking'?'Unpacking':'Awaiting delivery'}</span></td><td><button class="secondary" data-invoice-labels="${o.id}">Customer labels</button> <button class="secondary" data-invoice="${o.id}">${o.status==='checked'?'Review check-in':'Open invoice →'}</button></td></tr>`;}).join('')||'<tr><td colspan="7" class="empty">No invoices match. Use New invoice to enter one.</td></tr>'}</tbody></table></div></section><p class="hint">This desk checks supplier quantities only. Customer allocations and collection-label printing remain a separate customer-order workflow.</p>`;
document.querySelectorAll('[data-invoice-labels]').forEach(b=>b.onclick=()=>openInvoiceLabels(b.dataset.invoiceLabels));document.querySelectorAll('[data-invoice]').forEach(b=>b.onclick=()=>openInvoice(b.dataset.invoice));document.querySelectorAll('[data-invoice-filter]').forEach(b=>b.onclick=()=>{invoiceFilter=b.dataset.invoiceFilter;renderInvoiceDesk();});$('#invoice-search').oninput=e=>{invoiceSearch=e.target.value;const cursor=e.target.selectionStart;renderInvoiceDesk().then(()=>{if($('#invoice-search')){$('#invoice-search').focus();$('#invoice-search').setSelectionRange(cursor,cursor);}});};}catch(e){toast(e.message);}}
function showInvoiceDialog(html){$('#invoice-content').innerHTML=html;if(!$('#invoice-dialog').open)$('#invoice-dialog').showModal();bindClose();}
function invoiceHeader(title,subtitle='SUPPLIER DELIVERY CHECK-IN'){return `<div class="modal-heading"><div><div class="eyebrow">${esc(subtitle)}</div><h2>${esc(title)}</h2></div><button class="close" data-close="invoice-dialog" aria-label="Close">×</button></div>`;}
async function readEvidence(file,pdf=false){if(!file)return null;if(file.size>1000000)throw Error('Choose an image or PDF smaller than 1 MB.');if(!['image/jpeg','image/png','image/webp',...(pdf?['application/pdf']:[])].includes(file.type))throw Error('Choose a JPG, PNG, WebP image'+(pdf?' or PDF':'')+'.');return new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve({name:file.name,data:r.result});r.onerror=()=>reject(Error('Could not read this file.'));r.readAsDataURL(file);});}
function newInvoice(){showInvoiceDialog(invoiceHeader('Register a supplier invoice')+`<form id="invoice-new-form"><div class="form-body"><p>Enter every invoiced item, including stock-only goods. Nothing is copied from customer orders.</p><div class="form-grid"><label>Supplier<input name="supplier" required placeholder="Lehmanns, Friedman, Sifrei…"></label><label>Invoice number<input name="number" required placeholder="Supplier invoice reference"></label><label>Invoice date<input name="invoiceDate" type="date" value="${new Date().toISOString().slice(0,10)}" required></label><label>Expected arrival<input name="expectedDate" type="date" value="${new Date().toISOString().slice(0,10)}" required></label><label>Worker<input name="worker" value="${esc(invoiceWorker)}" required></label><label>Original invoice (optional)<input name="original" type="file" accept="application/pdf,image/jpeg,image/png,image/webp"></label></div><h3>Invoice contents</h3><p>Quantity means units shown on the invoice, not customer reservations.</p><div id="invoice-new-lines"></div><button type="button" id="invoice-add-line" class="secondary">＋ Add invoice item</button><p class="error" id="invoice-new-error" role="alert"></p></div><div class="modal-footer"><button class="primary">Save invoice</button></div></form>`);const add=()=>{const row=document.createElement('div');row.className='invoice-entry';row.innerHTML='<label>Code<input name="code" placeholder="SKU / ISBN"></label><label>Item title<input name="title" placeholder="Book or product" required></label><label>Qty<input name="quantity" type="number" min="1" max="10000" value="1" required></label><button type="button" class="close" aria-label="Remove item">×</button>';row.querySelector('button').onclick=()=>row.remove();$('#invoice-new-lines').append(row);};add();$('#invoice-add-line').onclick=add;$('#invoice-new-form').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.target);const button=e.target.querySelector('.primary');button.disabled=true;try{const originalFile=await readEvidence(f.get('original')?.size?f.get('original'):null,true);const lines=[...document.querySelectorAll('.invoice-entry')].map(row=>({code:row.querySelector('[name=code]').value,title:row.querySelector('[name=title]').value,quantity:Number(row.querySelector('[name=quantity]').value)}));const o=await api('/api/invoices',{number:f.get('number'),supplier:f.get('supplier'),invoiceDate:f.get('invoiceDate'),expectedDate:f.get('expectedDate'),worker:f.get('worker'),originalFile,lines});invoiceWorker=f.get('worker');await refreshInvoices();openInvoice(o.id);if(view==='deliveries')renderInvoiceDesk();toast('Invoice saved separately from customer orders');}catch(err){$('#invoice-new-error').textContent=err.message;}finally{if(button.isConnected)button.disabled=false;}};}
async function changeInvoice(o,action,extra={}){try{const result=await api('/api/invoices/'+o.id,{action,version:o.version,worker:invoiceWorker,...extra});await refreshInvoices();if(view==='deliveries')renderInvoiceDesk();openInvoice(result.id);toast(action==='finish'?'Invoice check-in completed and saved':'Invoice saved');return true;}catch(e){toast(e.message);return false;}}
function openInvoice(id){const o=invoices.find(x=>x.id===id);if(!o)return;const t=DeliveryModel.totals(o),editing=o.status==='checking';let evidence=new Map(o.lines.map(l=>[l.id,[...l.photos]]));showInvoiceDialog(invoiceHeader(o.number,o.supplier+' · INVOICE CHECKLIST · NO CUSTOMER DATA')+`<div class="detail-body"><div class="invoice-summary"><div><small>Invoiced</small><strong>${t.invoiced}</strong></div><div><small>Good received</small><strong>${t.good}</strong></div><div><small>Damaged</small><strong>${t.damaged}</strong></div><div><small>Missing · checked lines</small><strong>${t.missing}</strong></div><div><small>Unchecked lines</small><strong>${t.unchecked}</strong></div></div><div class="detail-actions"><button type="button" class="primary" id="invoice-customer-labels">Customer packing list & labels →</button></div><div class="invoice-meta"><span>Invoice date: ${date(o.invoiceDate)} · Expected: ${date(o.expectedDate)}</span><label>Checking worker <input id="invoice-worker" value="${esc(invoiceWorker)}" required></label>${o.originalFile?`<a class="secondary" href="${esc(o.originalFile.data)}" download="${esc(o.originalFile.name)}">Download original invoice</a>`:''}</div>${o.status==='awaiting'?'<p class="hint">Start when this delivery arrives. Every invoice line must be checked before completion.</p><button id="start-invoice" class="primary">Start unpacking this invoice →</button>':''}${o.status==='checked'?`<p class="hint">Completed ${timestamp(o.completedAt)}. This result is saved; later reviews preserve every previous completed check.</p><div class="detail-actions"><button class="secondary" id="review-invoice">Reopen for a correction / replacement</button><button class="secondary" id="print-checklist">Print check-in report</button></div>`:''}<form id="invoice-check-form"><div class="table-wrap"><table class="invoice-check"><thead><tr><th>Checked</th><th>Item / code</th><th>Invoiced</th><th>Good received</th><th>Damaged</th><th>Missing</th><th>Notes & evidence</th></tr></thead><tbody>${o.lines.map(l=>`<tr data-invoice-line="${l.id}"><td><input type="checkbox" name="checked" aria-label="Checked ${esc(l.title)}" ${l.checked?'checked':''} ${!editing?'disabled':''}></td><td><strong>${esc(l.title)}</strong><small class="subtext">${esc(l.code)}</small>${editing?'<button type="button" class="text-button" data-full="'+l.id+'">All received ✓</button>':''}</td><td>${l.quantity}</td><td><input name="good" aria-label="Good received ${esc(l.title)}" type="number" min="0" max="${l.quantity}" value="${l.good}" ${!editing?'disabled':''}></td><td><input name="damaged" aria-label="Damaged ${esc(l.title)}" type="number" min="0" max="${l.quantity}" value="${l.damaged}" ${!editing?'disabled':''}></td><td class="invoice-missing">${l.checked?l.quantity-l.good-l.damaged:'Unchecked'}</td><td><textarea name="notes" aria-label="Notes ${esc(l.title)}" ${!editing?'disabled':''} placeholder="Condition, shortage…">${esc(l.notes)}</textarea><div class="invoice-photos">${l.photos.map(p=>`<img src="${esc(p.data)}" alt="${esc(p.name)}" class="evidence-photo">`).join('')}</div>${editing?`<input type="file" name="photo" aria-label="Damage photo ${esc(l.title)}" accept="image/jpeg,image/png,image/webp" capture="environment"><small class="subtext">${l.photos.length} saved photo(s) · max 3</small>`:''}</td></tr>`).join('')}</tbody></table></div>${editing?'<p class="hint">Unchecked is not missing. Count the goods, enter damaged quantities and tick each line. “All received” fills the complete good quantity for that line.</p><div class="detail-actions"><button type="button" class="secondary" id="mark-unchecked-missing">Mark remaining unchecked lines as missing</button><button type="submit" class="secondary" id="save-invoice-progress">Save progress</button><button type="button" class="primary" id="finish-invoice">Finish invoice check-in →</button></div>':''}</form><div id="invoice-review-form"></div>${o.status==='checked'?invoiceDraftPanel(o):''}<h3>Saved check-in history</h3><div class="timeline">${[...o.history].reverse().map(h=>`<div class="event"><p>${esc(h.text)}</p><small>${timestamp(h.at)} · ${esc(h.by)}</small></div>`).join('')}</div>${o.reviews.length?`<details><summary>Review previous completed checks (${o.reviews.length})</summary>${o.reviews.map((r,i)=>`<div class="card saved-review"><strong>Check ${i+1} · ${timestamp(r.at)} · ${esc(r.by)}</strong><p>${r.totals.good} good · ${r.totals.missing} missing · ${r.totals.damaged} damaged</p>${r.lines.map(l=>`<p>${esc(l.code)} ${esc(l.title)} — good ${l.good}, damaged ${l.damaged}, missing ${l.quantity-l.good-l.damaged}${l.notes?' · '+esc(l.notes):''}</p>${l.photos.map(p=>`<img class="evidence-photo" src="${esc(p.data)}" alt="${esc(p.name)}">`).join('')}`).join('')}</div>`).join('')}</details>`:''}<form id="invoice-note-form"><label class="field-label">Supplier follow-up / resolution<textarea class="note-input" name="note" placeholder="Supplier promised replacements, credit received…" required></textarea></label><button class="secondary">Save follow-up note</button></form></div>`);
$('#invoice-customer-labels').onclick=()=>openInvoiceLabels(o.id);
$('#invoice-worker').onchange=e=>invoiceWorker=e.target.value;const collect=()=>o.lines.map(l=>{const row=document.querySelector(`[data-invoice-line="${l.id}"]`);return {id:l.id,checked:row.querySelector('[name=checked]').checked,good:Number(row.querySelector('[name=good]').value),damaged:Number(row.querySelector('[name=damaged]').value),notes:row.querySelector('[name=notes]').value,photos:evidence.get(l.id)};});
if($('#start-invoice'))$('#start-invoice').onclick=()=>changeInvoice(o,'start');
if(editing){const recalc=row=>{const l=o.lines.find(l=>l.id===row.dataset.invoiceLine),good=Number(row.querySelector('[name=good]').value),damaged=Number(row.querySelector('[name=damaged]').value);row.querySelector('.invoice-missing').textContent=row.querySelector('[name=checked]').checked?l.quantity-good-damaged:'Unchecked';};document.querySelectorAll('[data-invoice-line]').forEach(row=>{row.querySelectorAll('input[type=number],input[type=checkbox]').forEach(input=>input.oninput=()=>recalc(row));const input=row.querySelector('[name=photo]');input.onchange=async()=>{try{const photo=await readEvidence(input.files[0]);const photos=evidence.get(row.dataset.invoiceLine);if(photos.length>=3)throw Error('At most three photos per line.');if(photo)photos.push(photo);const img=document.createElement('img');img.className='evidence-photo';img.alt=photo.name;img.src=photo.data;row.querySelector('.invoice-photos').append(img);toast('Photo ready. Save progress to keep it.');}catch(err){toast(err.message);}};});document.querySelectorAll('[data-full]').forEach(b=>b.onclick=()=>{const row=b.closest('tr'),l=o.lines.find(x=>x.id===b.dataset.full);row.querySelector('[name=good]').value=l.quantity;row.querySelector('[name=damaged]').value=0;row.querySelector('[name=checked]').checked=true;recalc(row);});$('#mark-unchecked-missing').onclick=()=>{const rows=[...document.querySelectorAll('[data-invoice-line]')].filter(row=>!row.querySelector('[name=checked]').checked);if(rows.some(row=>Number(row.querySelector('[name=good]').value)||Number(row.querySelector('[name=damaged]').value)))return toast('Some unchecked lines contain quantities. Check those lines first.');if(rows.length&&!confirm(`Mark ${rows.length} unchecked line(s) as entirely missing?`))return;rows.forEach(row=>{row.querySelector('[name=checked]').checked=true;recalc(row);});};$('#invoice-check-form').onsubmit=async e=>{e.preventDefault();await changeInvoice(o,'save',{lines:collect()});};$('#finish-invoice').onclick=async()=>{const lines=collect();if(lines.some(l=>!l.checked))return toast('Some lines are unchecked. Check them or explicitly mark them missing first.');await changeInvoice(o,'finish',{lines});};}
if($('#review-invoice'))$('#review-invoice').onclick=()=>{$('#invoice-review-form').innerHTML='<form id="reopen-invoice-form" class="card"><label class="field-label">Why are you reopening this check?<textarea class="note-input" name="reason" required placeholder="Replacement arrived, counting correction…"></textarea></label><button class="primary">Reopen and keep previous check</button></form>';$('#reopen-invoice-form').onsubmit=async e=>{e.preventDefault();await changeInvoice(o,'reopen',{reason:new FormData(e.target).get('reason')});};};$('#invoice-note-form').onsubmit=async e=>{e.preventDefault();await changeInvoice(o,'note',{note:new FormData(e.target).get('note')});};
if($('#invoice-copy-draft'))$('#invoice-copy-draft').onclick=async()=>{try{await navigator.clipboard.writeText($('#invoice-draft-text').value);toast('Supplier draft copied. Nothing sent.');}catch{toast('Select the supplier draft text and copy it.');}};
if($('#print-checklist'))$('#print-checklist').onclick=()=>{const area=$('#print-area');area.innerHTML=`<article class="invoice-print"><h2>${esc(o.supplier)} · Invoice ${esc(o.number)}</h2><p>Checked ${timestamp(o.completedAt)} · ${t.good} good, ${t.missing} missing, ${t.damaged} damaged</p><table><thead><tr><th>Code / item</th><th>Invoiced</th><th>Good</th><th>Damaged</th><th>Missing</th></tr></thead><tbody>${o.lines.map(l=>`<tr><td>${esc(l.code)} ${esc(l.title)}</td><td>${l.quantity}</td><td>${l.good}</td><td>${l.damaged}</td><td>${l.quantity-l.good-l.damaged}</td></tr>`).join('')}</tbody></table></article>`;window.print();};
}
function invoiceDraftPanel(o){const draft=DeliveryModel.draft(o);return `<section class="card invoice-draft"><h3>${draft?'Supplier shortage / damage draft':'Invoice checked · no shortages or damage'}</h3>${draft?`<p>One draft for this entire invoice. No customer names or allocations are included. Gmail is not connected here; copy and review before sending. Saved photos and the original invoice are retained in this check-in, not automatically attached to email.</p><textarea class="note-input" id="invoice-draft-text" rows="12">${esc(draft)}</textarea><button class="secondary" id="invoice-copy-draft">Copy supplier draft</button>`:'<p>All invoiced quantities were received in good condition. No supplier complaint is needed.</p>'}</section>`;}

async function openInvoiceLabels(id){try{await refreshInvoices();const o=invoices.find(x=>x.id===id);const allocation=await api('/api/invoice-allocations/'+id);let rows=allocation.rows.map(r=>({...r}));function draw(){showInvoiceDialog(invoiceHeader('Customer packing list · '+o.number,'SEPARATE FROM THE SUPPLIER CHECKLIST')+`<div class="detail-body"><div class="detail-actions"><button class="secondary" id="back-to-supplier">← Supplier checklist</button><button class="primary" id="print-invoice-labels">Print saved customer labels</button></div><p>See which goods on this invoice are reserved for customers. The remaining invoiced quantities are planned shop stock. This list is separate: customer names never enter the supplier report or complaint draft.</p><p class="hint">Sample reservations are included for the demo invoices. First save good received quantities in the supplier checklist. Then confirm ready quantities here and save the packing list before printing.</p><form id="packing-form"><div class="table-wrap"><table class="packing-table"><thead><tr><th>Invoice item</th><th>Customer / order</th><th>Reserved</th><th>Ready to label</th><th>Collection location</th><th></th></tr></thead><tbody>${rows.map((r,i)=>`<tr data-packing-index="${i}"><td><select name="lineId" aria-label="Item for reservation ${i+1}">${o.lines.map(l=>`<option value="${l.id}" ${r.lineId===l.id?'selected':''}>${esc(l.title)}</option>`).join('')}</select></td><td><input name="customer" aria-label="Customer ${i+1}" value="${esc(r.customer)}" placeholder="Customer name" required><input name="orderReference" aria-label="Order reference ${i+1}" value="${esc(r.orderReference)}" placeholder="Order reference"></td><td><input type="number" name="reserved" aria-label="Reserved quantity ${i+1}" min="1" value="${r.reserved}" required></td><td><input type="number" name="ready" aria-label="Ready quantity ${i+1}" min="0" value="${r.ready}" required></td><td><input name="location" aria-label="Collection location ${i+1}" value="${esc(r.location)}" placeholder="Collection shelf"></td><td><button type="button" class="close" data-remove-packing="${i}" aria-label="Remove reservation ${i+1}">×</button></td></tr>`).join('')||'<tr><td colspan="6">No customer reservations yet. All items are planned for shop stock.</td></tr>'}</tbody></table></div><div class="detail-actions"><button type="button" class="secondary" id="add-packing">＋ Add customer reservation</button><button type="button" class="secondary" id="fill-packing-ready">Fill ready quantities from received goods</button><button class="primary">Save customer packing list</button></div><p class="error" id="packing-error" role="alert"></p></form><h3>Shop stock & received allocation</h3><div class="table-wrap"><table><thead><tr><th>Item</th><th>Invoiced</th><th>Customer reservations</th><th>Planned shop stock</th><th>Good received</th><th>Ready for customers</th><th>Good units not allocated</th></tr></thead><tbody>${o.lines.map(l=>{const reserved=rows.filter(r=>r.lineId===l.id).reduce((n,r)=>n+r.reserved,0),ready=rows.filter(r=>r.lineId===l.id).reduce((n,r)=>n+r.ready,0),good=l.checked?l.good:0;return `<tr><td>${esc(l.title)}</td><td>${l.quantity}</td><td>${reserved}</td><td>${Math.max(0,l.quantity-reserved)}</td><td>${good}</td><td>${ready}</td><td>${Math.max(0,good-ready)}</td></tr>`;}).join('')}</tbody></table></div><p class="hint">Good units not allocated includes shop stock and goods still awaiting a customer allocation decision. Missing or damaged items cannot be printed as ready. Customer order statuses and messages are not changed by this screen.</p></div>`);
const collect=()=>[...document.querySelectorAll('[data-packing-index]')].map(row=>{const original=rows[Number(row.dataset.packingIndex)];const value=n=>row.querySelector('[name='+n+']').value;return {...original,lineId:value('lineId'),customer:value('customer'),orderReference:value('orderReference'),reserved:Number(value('reserved')),ready:Number(value('ready')),location:value('location')};});
$('#back-to-supplier').onclick=()=>openInvoice(id);$('#add-packing').onclick=()=>{rows=collect();rows.push({id:'reservation-'+Date.now()+'-'+Math.random().toString(16).slice(2),lineId:o.lines[0].id,customer:'',orderReference:'',reserved:1,ready:0,location:''});draw();};document.querySelectorAll('[data-remove-packing]').forEach(b=>b.onclick=()=>{rows=collect();rows.splice(Number(b.dataset.removePacking),1);draw();});$('#fill-packing-ready').onclick=()=>{rows=collect();const remaining=Object.fromEntries(o.lines.map(l=>[l.id,l.checked?l.good:0]));for(const r of rows){r.ready=Math.min(r.reserved,remaining[r.lineId]);remaining[r.lineId]-=r.ready;}draw();toast('Quantities filled in row order. Review and save before printing.');};$('#packing-form').onsubmit=async e=>{e.preventDefault();try{const saved=await api('/api/invoice-allocations/'+id,{version:allocation.version,rows:collect()});allocation.version=saved.version;allocation.rows=saved.rows;rows=saved.rows.map(r=>({...r}));draw();toast('Customer packing list saved separately from supplier records');}catch(err){$('#packing-error').textContent=err.message;}};
$('#print-invoice-labels').onclick=()=>{try{if(JSON.stringify(collect())!==JSON.stringify(allocation.rows))return toast('Save changes before printing.');const labels=DeliveryModel.allocationLabels(o,allocation);const count=labels.reduce((n,r)=>n+r.ready,0);if(!count)return toast('No customer items are ready to label. Save good received quantities, then allocate them to customers.');if(count>500)return toast('Print at most 500 labels at a time.');$('#print-area').innerHTML=labels.flatMap(r=>Array.from({length:r.ready},(_,i)=>`<div class="label"><small>TIFERES · ${esc(r.orderReference||o.number)}</small><h2>${esc(r.customer)}</h2><p>${esc(r.title)}<br>${esc(r.code)}</p><p>Item ${i+1} of ${r.ready} · Invoice ${esc(o.number)}<br>Location: ${esc(r.location||'Not assigned')}</p></div>`)).join('');window.print();}catch(err){toast(err.message);}};
}draw();}catch(e){toast(e.message);}}
